<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {api} from './api';
import {locale} from './i18n';
const props=defineProps<{query:string;canManage:boolean}>();
const th=computed(()=>locale.value==='th-TH');
type Case={id:number;status:string;agent:string;agentId:number;ip:string;actor:string;rule:string;explanation:string;owner:string|null;resolutionNote:string|null;evidenceCount:number;firstLogId:number;lastLogId:number};
const rows=ref<Case[]>([]),error=ref(''),busy=ref(false),truncated=ref(false),editing=ref<Case|null>(null),note=ref(''),owner=ref('');
let generation=0;
async function load(){const current=++generation;error.value='';try{const r=await api<{cases:Case[];truncated:boolean}>(`/api/threats/cases?${props.query}`);if(current===generation){rows.value=r.cases;truncated.value=r.truncated;}}catch(e){if(current===generation){rows.value=[];error.value=e instanceof Error?e.message:String(e);}}}
async function save(status:string){if(!editing.value)return;busy.value=true;error.value='';try{await api(`/api/findings/${editing.value.id}`,{method:'PUT',body:JSON.stringify({status,owner:owner.value,resolutionNote:note.value})});editing.value=null;await load();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
watch(()=>props.query,()=>{editing.value=null;void load();},{immediate:true});
</script>
<template><details class="panel threat-cases"><summary>{{th?'เคสที่เกี่ยวข้อง':'Related cases'}} ({{rows.length}}{{truncated?'+':''}})</summary><p>{{th?'กรองตามเครื่อง IP และช่วงเวลาที่ตรวจพบ ไม่ใช้ตัวกรองชนิด Log รับทราบไม่ใช่ปิดเคส เมื่อปิดแล้วต้องมีหลักฐานใหม่ครบเกณฑ์จึงเปิดอีกครั้ง':'Scoped by machine, IP and detection period, not log type filters. Acknowledgement is not closure. Reopening requires a fresh threshold of evidence.'}}</p><p v-if="error" role="alert">{{error}}</p><p v-if="!rows.length&&!error">{{th?'ยังไม่มีเคสตามเงื่อนไข':'No matching cases'}}</p><article v-for="row in rows" :key="row.id"><strong>#{{row.id}} · {{row.agent}} · {{row.ip||'—'}} · {{row.actor||'—'}}</strong><p>{{row.rule}} · {{row.status}} · {{th?'หลักฐาน':'Evidence'}} #{{row.firstLogId}}–#{{row.lastLogId}}</p><p>{{row.explanation}}</p><button v-if="canManage" class="secondary" @click="editing={...row};note=row.resolutionNote||'';owner=row.owner||''">{{th?'จัดการเคส':'Manage case'}}</button></article><form v-if="editing" @submit.prevent="save('RESOLVED')"><h3>#{{editing.id}}</h3><label>{{th?'ผู้รับผิดชอบ':'Owner'}}<input v-model="owner" maxlength="150"></label><label>{{th?'ผลตรวจสอบและวิธีแก้ไข':'Investigation and remediation'}}<textarea v-model="note" maxlength="2000" required /></label><div><button type="button" class="secondary" :disabled="busy" @click="save('ACKNOWLEDGED')">{{th?'รับทราบ':'Acknowledge'}}</button> <button class="primary" :disabled="busy||!note.trim()">{{th?'ปิดเคส':'Resolve'}}</button> <button type="button" class="link" :disabled="busy" @click="editing=null">{{th?'ยกเลิก':'Cancel'}}</button></div></form><p v-if="truncated">{{th?'แสดง 200 เคสแรก กรุณากรองเพิ่ม':'First 200 cases shown; narrow filters'}}</p></details></template>
<style scoped>.threat-cases{padding:20px;margin-bottom:20px}.threat-cases summary{cursor:pointer;font-weight:600}.threat-cases p{color:#adbed3;font-size:13px;line-height:1.7;overflow-wrap:anywhere}.threat-cases article{padding:14px 0;border-top:1px solid #2b394e}.threat-cases form{padding:18px;border:1px solid #465973;border-radius:8px}.threat-cases label{margin-bottom:12px}</style>
